using System;
using System.Linq;
using System.Globalization;
namespace IdleIntelligence.Core
{
 [Serializable]public sealed class CapsuleReceipt
 {public long id;public double at;public string payment,kind,itemId="",itemType="",resourceId="";public int rarity;public bool hasResource;public NumberData amount;public long[] components=new long[ItemBalance.ComponentIds.Length];public CapsuleReceipt Copy(){var r=(CapsuleReceipt)MemberwiseClone();r.components=(long[])components.Clone();r.amount=hasResource?ScientificNumber.FromData(amount).ToData():null;return r;}}
 [Serializable]public sealed class CapsuleState
 {public int schema=1;public bool initialized,hasLast,hasRequest;public long draws,items;public CapsuleReceipt last;public string day="";public int videos;public string[] videoTransactions=Array.Empty<string>();public MarketAdTicket request;public static CapsuleState New(double at)=>new CapsuleState{initialized=true,day=MissionCalendar.Key(at,0)};public CapsuleState Copy(){var c=(CapsuleState)MemberwiseClone();c.last=hasLast?last?.Copy():null;c.videoTransactions=(string[])videoTransactions.Clone();c.request=hasRequest?request?.Copy():null;return c;}}
 public sealed class CapsuleQuote{public string Reason;public bool Allowed,VideoAllowed;public int VideoRemaining;public long Next;}
 public static class Capsules
 {
  const long Max=9007199254740991L;
  public static CapsuleQuote Quote(GameState s){string reason=ChallengeRules.Active(s)?"challenge":s.Prestige.resets<1?"prestige":s.Capsules.draws>=Max?"limit":null;int used=s.Capsules.day==MissionCalendar.Key(s.SavedAt,0)?s.Capsules.videos:0;return new CapsuleQuote{Reason=reason,Next=s.Capsules.draws+1,Allowed=reason==null&&s.Retention.gems>=GemBalance.CapsuleCost,VideoAllowed=reason==null&&used<GemBalance.CapsuleVideoLimit,VideoRemaining=(int)Math.Max(0,GemBalance.CapsuleVideoLimit-used)};}
  static Func<double> Rolls(GameState s,string key){int n=0;return()=>BonusBoxes.Roll(s.Missions.campaign,"capsule:"+key+":"+n++);}
  static GameState Grant(GameState state,long id,string payment,Func<double> rng,double at)
  {
   var q=Quote(state);if(q.Reason!=null||id!=q.Next)return state;Func<double> random=()=>{double v=rng();if(!ScientificNumber.Finite(v)||v<0||v>=1)throw new ArgumentOutOfRangeException(nameof(rng));return v;};var s=state;string itemId="",itemType="",kind="components",resourceId="";int rarity=0;NumberData resource=null;var components=new long[ItemBalance.ComponentIds.Length];double roll=random();
   if(roll<GemBalance.ItemChance){var pool=SeasonRules.Pool(s);if(pool.Length==0)return state;random();string type=pool[(int)Math.Floor(random()*pool.Length)];s=RetentionRules.CreateItem(s,type,0);if(ReferenceEquals(s,state))return state;itemId=s.Workshop.inventory.Last().id;itemType=type;kind="item";}
   else if(roll<GemBalance.ItemChance+GemBalance.ComponentChance){var ids=ItemBalance.MaterialFamilies.SelectMany((list,f)=>MaterialAnalysis.Access(s,f)?list:Array.Empty<string>()).ToArray();double value=random(),chance=1d/ids.Length;int c=ids.Length-1;for(int i=0;i<ids.Length;i++){value-=chance;if(value<0){c=i;break;}}if(ids.Length==0)return state;rarity=chance<GemBalance.RareBoundary?2:chance<GemBalance.UncommonBoundary?1:0;var range=GemBalance.ComponentRanges[rarity];long amount=(long)(range[0]+Math.Floor(random()*(range[1]-range[0]+1)));int component=Array.IndexOf(ItemBalance.ComponentIds,ids[c]);if(s.Workshop.components[component]>Max-amount||s.Workshop.components.Sum()>Max-amount||s.Lifetime.componentsEarned>Max-amount||Math.Floor(s.Lifetime.componentsEarned+amount)!=s.Lifetime.componentsEarned+amount)return state;s=s.Copy();components[component]=amount;s.Workshop.components[component]+=amount;Lifetime.Components(s,component,amount);}
   else{double componentEnd=Math.Round(GemBalance.ItemChance+GemBalance.ComponentChance,10,MidpointRounding.AwayFromZero),creditEnd=Math.Round(componentEnd+GemBalance.CreditChance,10,MidpointRounding.AwayFromZero),dataEnd=Math.Round(creditEnd+GemBalance.DataChance,10,MidpointRounding.AwayFromZero);kind=roll<creditEnd?"credits":roll<dataEnd?"data":roll<1-GemBalance.JackpotChance?"gems":"jackpot";s=s.Copy();if(kind=="credits"||kind=="data"){var range=kind=="credits"?GemBalance.CreditSeconds:GemBalance.DataSeconds;double seconds=range[0]+Math.Floor(random()*(range[1]-range[0]+1));var rate=kind=="credits"?Game.Income(s,false):Game.DataRate(s);var raw=rate.Times(seconds);var floor=ScientificNumber.From(kind=="credits"?GemBalance.CreditFloor:GemBalance.DataFloor);var amount=raw.CompareTo(floor)<0?floor:raw;resourceId=kind;resource=amount.ToData();if(kind=="credits")s.Credits=s.Credits.Add(amount);else{s.Data=s.Data.Add(amount);Lifetime.Produced(s,ScientificNumber.Zero,amount);}}else{long amount=(long)(kind=="jackpot"?GemBalance.CapsuleCost*GemBalance.JackpotMultiplier:GemBalance.GemRange[0]+Math.Floor(random()*(GemBalance.GemRange[1]-GemBalance.GemRange[0]+1)));if(s.Retention.gems>Max-amount)return state;resourceId="gems";resource=ScientificNumber.From(amount).ToData();RetentionRules.Gems(s,amount,"capsule-reward-"+id,"capsule-reward");s.Retention.ledger[s.Retention.ledger.Length-1].at=at;}}
   s=s.Copy();s.Capsules.draws=id;s.Capsules.items=state.Capsules.items+(kind=="item"?1:0);s.Capsules.hasLast=true;s.Capsules.last=new CapsuleReceipt{id=id,at=at,payment=payment,kind=kind,rarity=rarity,itemId=itemId,itemType=itemType,hasResource=resource!=null,resourceId=resourceId,amount=resource,components=components};s.Workshop.revision++;return s;
  }
  public static GameState Draw(GameState state,long id,Func<double> rng=null)
  {if(!Quote(state).Allowed)return state;var paid=state.Copy();RetentionRules.Gems(paid,-(long)GemBalance.CapsuleCost,"capsule-"+id,"capsule-machine");var next=Grant(paid,id,"gems",rng??Rolls(state,"gem:"+id),state.SavedAt);return ReferenceEquals(next,paid)?state:next;}
  public static GameState RewardVideo(GameState state,string tx,string result,double now,Func<double> rng=null)
  {if(result!="success"||string.IsNullOrEmpty(tx)||tx.Length>160||!ScientificNumber.Finite(now)||now<0||now>8.64e15||state.Capsules.videoTransactions.Contains(tx))return state;var quote=state.Copy();quote.SavedAt=now;if(!Quote(quote).VideoAllowed)return state;var next=Grant(state,state.Capsules.draws+1,"video",rng??Rolls(state,"video:"+tx),now);if(ReferenceEquals(next,state))return state;string day=MissionCalendar.Key(now,0);next.Capsules.videos=(state.Capsules.day==day?state.Capsules.videos:0)+1;next.Capsules.day=day;next.Capsules.videoTransactions=state.Capsules.videoTransactions.Concat(new[]{tx}).ToArray();return next;}
  public static GameState BeginVideo(GameState state,string tx)
  {if(string.IsNullOrEmpty(tx)||tx.Length>160||!Quote(state).VideoAllowed||state.Capsules.hasRequest)return state;var s=state.Copy();s.Capsules.hasRequest=true;s.Capsules.request=new MarketAdTicket{id=tx,at=s.SavedAt,expiresAt=s.SavedAt+MarketBalance.AdTicketMilliseconds,context=Market.Context(s)};return s;}
  public static GameState CancelVideo(GameState state,string tx){if(!state.Capsules.hasRequest||state.Capsules.request.id!=tx)return state;var s=state.Copy();s.Capsules.hasRequest=false;s.Capsules.request=null;return s;}
  public static GameState CompleteRequestedVideo(GameState state,string tx,string result)
  {var request=state.Capsules.hasRequest?state.Capsules.request:null;if(request==null||request.id!=tx)return state;var cleared=CancelVideo(state,tx);return result=="success"&&request.context==Market.Context(state)&&state.SavedAt<=request.expiresAt?RewardVideo(cleared,tx,result,state.SavedAt):cleared;}
  public static void Validate(GameState s)
  {var c=s.Capsules;if(c==null||!c.initialized||c.schema!=1||c.draws<0||c.draws>Max||c.items<0||c.items>c.draws||c.day==null||c.videos<0||c.videos>GemBalance.CapsuleVideoLimit||c.videoTransactions==null||c.videoTransactions.Any(tx=>string.IsNullOrEmpty(tx)||tx.Length>160)||c.videoTransactions.Distinct().Count()!=c.videoTransactions.Length||c.draws==0&&(c.items!=0||c.hasLast)||c.draws>0&&!c.hasLast)throw new FormatException("Invalid capsule state");if(c.hasLast){var r=c.last;if(r==null||r.id!=c.draws||!ScientificNumber.Finite(r.at)||r.at<0||r.at>8.64e15||!new[]{"gems","video"}.Contains(r.payment)||r.rarity<0||r.rarity>=ItemBalance.RarityFactors.Length||r.components==null||r.components.Length!=ItemBalance.ComponentIds.Length)throw new FormatException("Invalid capsule receipt");if(new[]{"credits","data","gems","jackpot"}.Contains(r.kind)){var amount=r.hasResource?ScientificNumber.FromData(r.amount):ScientificNumber.Zero;if(r.itemId!=""||r.itemType!=""||r.components.Any(n=>n!=0)||!r.hasResource||r.resourceId!=(r.kind=="gems"||r.kind=="jackpot"?"gems":r.kind)||amount.IsZero||r.resourceId=="gems"&&(amount.ToDouble()>Max||Math.Floor(amount.ToDouble())!=amount.ToDouble()))throw new FormatException("Invalid capsule resource");}else if(r.hasResource||r.kind=="item"&&(c.items==0||string.IsNullOrEmpty(r.itemId)||Workshop.Index(r.itemType)<0||r.components.Any(n=>n!=0))||r.kind=="components"&&(r.itemId!=""||r.itemType!=""||r.components.Count(n=>n!=0)!=1||r.components.Any(n=>n<0||n>GemBalance.ComponentRanges[0][1]))||!new[]{"item","components"}.Contains(r.kind))throw new FormatException("Invalid capsule item/material");}if(c.hasRequest){var p=c.request;if(p==null||string.IsNullOrEmpty(p.id)||p.id.Length>160||!ScientificNumber.Finite(p.at)||p.at<0||p.expiresAt-p.at!=MarketBalance.AdTicketMilliseconds||p.context==null||p.context.Length>1000)throw new FormatException("Invalid capsule provider request");}}
 }
}
